//! Wolfram exact-solution replay through the public facade.
//!
//! The fixture (`sonium-qa/wolfram/goldens/exact-linear-algebra-v1.json`,
//! generated by `sonium-qa/wolfram/exact_linear_algebra.wls`) carries exact
//! systems with known solutions, per audit-sonium-solvers-20260921 (test the
//! public facade with independently solved exact matrices; check
//! original-system residuals). Both residual and solution error are asserted
//! together since an ill-conditioned system can show a small residual with a
//! large solution error.

use serde::Deserialize;
use sonium_solvers::{
    CsrMatrix, LinearSolveConfig, LinearSolverType, LinearSystemAssumption, solve,
    solve_with_assumption,
};

const FIXTURE: &str = include_str!("../../sonium-qa/wolfram/goldens/exact-linear-algebra-v1.json");

#[derive(Debug, Deserialize)]
struct RealSystem {
    a: Vec<Vec<String>>,
    x_exact: Vec<String>,
    b: Vec<String>,
}

#[derive(Debug, Deserialize)]
struct DiagSystem {
    diag: Vec<String>,
    x_exact: Vec<String>,
    b: Vec<String>,
}

#[derive(Debug, Deserialize)]
struct Fixture {
    schema: String,
    nonsym_3x3: RealSystem,
    hilbert_4x4: RealSystem,
    illscaled_diag_4x4: DiagSystem,
}

fn parse(value: &str) -> f64 {
    value.parse().expect("fixture value is a decimal")
}

fn parse_fixture() -> Fixture {
    let fixture: Fixture =
        serde_json::from_str(FIXTURE).expect("valid exact linear-algebra fixture");
    assert_eq!(fixture.schema, "sonium-qa.exact-linear-algebra.v1");
    fixture
}

fn csr(system: &RealSystem) -> (CsrMatrix<f64>, Vec<f64>, Vec<f64>) {
    let n = system.a.len();
    let triplets = system
        .a
        .iter()
        .enumerate()
        .flat_map(|(i, row)| {
            row.iter()
                .enumerate()
                .map(move |(j, value)| (i, j, parse(value)))
        })
        .collect();
    let matrix = CsrMatrix::from_triplets(n, system.a[0].len(), triplets);
    let x_exact: Vec<f64> = system.x_exact.iter().map(|value| parse(value)).collect();
    let b: Vec<f64> = system.b.iter().map(|value| parse(value)).collect();
    (matrix, x_exact, b)
}

fn rel_error(x: &[f64], exact: &[f64]) -> f64 {
    let (mut num, mut den) = (0.0, 0.0);
    for (a, b) in x.iter().zip(exact.iter()) {
        num += (a - b) * (a - b);
        den += b * b;
    }
    num.sqrt() / den.sqrt()
}

fn tight_config() -> LinearSolveConfig {
    LinearSolveConfig {
        max_iterations: 1000,
        tolerance: 1e-12,
        restart: 30,
        ..Default::default()
    }
}

#[test]
fn facade_nonsymmetric_matches_wolfram_solution() {
    let fixture = parse_fixture();
    let (matrix, x_exact, b) = csr(&fixture.nonsym_3x3);
    let result = solve(&matrix, &b, &tight_config()).expect("nonsym facade solve failed");
    assert!(result.converged);
    assert!(
        result.backward_error <= 1e-10,
        "backward error {}",
        result.backward_error
    );
    assert!(
        rel_error(&result.x, &x_exact) <= 1e-9,
        "solution error vs wolfram x"
    );
}

#[test]
fn facade_hilbert_matches_wolfram_solution() {
    let fixture = parse_fixture();
    let (matrix, x_exact, b) = csr(&fixture.hilbert_4x4);
    // Explicit unpreconditioned GMRES: ILU without pivoting cannot factor
    // Hilbert (small pivots), which is itself selection evidence — Auto's
    // ILU default is not universal.
    let config = LinearSolveConfig {
        solver: LinearSolverType::Gmres,
        ..tight_config()
    };
    let result = solve(&matrix, &b, &config).expect("hilbert facade solve failed");
    assert!(result.converged);
    // Ill-conditioned (cond ~ 1.5e4): residual and solution error are
    // asserted together since they separate here.
    assert!(
        result.backward_error <= 1e-10,
        "backward error {}",
        result.backward_error
    );
    assert!(
        rel_error(&result.x, &x_exact) <= 1e-7,
        "solution error vs wolfram x"
    );
}

#[test]
fn facade_illscaled_matches_wolfram_solution() {
    let fixture = parse_fixture();
    let system = &fixture.illscaled_diag_4x4;
    let n = system.diag.len();
    let triplets = system
        .diag
        .iter()
        .enumerate()
        .map(|(i, value)| (i, i, parse(value)))
        .collect();
    let matrix = CsrMatrix::from_triplets(n, n, triplets);
    let x_exact: Vec<f64> = system.x_exact.iter().map(|value| parse(value)).collect();
    let b: Vec<f64> = system.b.iter().map(|value| parse(value)).collect();
    let config = LinearSolveConfig {
        solver: LinearSolverType::GmresIlu,
        ..tight_config()
    };
    let result = solve_with_assumption(&matrix, &b, &config, LinearSystemAssumption::General)
        .expect("ill-scaled facade solve failed");
    assert!(result.converged);
    assert!(
        rel_error(&result.x, &x_exact) <= 1e-9,
        "solution error vs wolfram x"
    );
}
